INSERT INTO medical_orders VALUES(241,'08011C','全套血液檢查Ｉ（八項）','CBC-I(WBC,RBC,HB,HCT,PLATELET COUNT,MCV,MCH,MCHC)','檢查',200,'',19950501,29101231,replace('(檢查)08011C - 全套血液檢查Ｉ（八項） 審查原則：(113/1/1)\n1.需符合檢查適應症，並有明確臨床需求。\n2.應檢附檢查申請單及檢查報告。\n3.重複檢查需間隔適當時間，並有明確臨床必要性說明。\n4.檢查結果應詳細記錄於病歷。','\n',char(10)),'2026-03-21 04:01:55','2026-03-21 04:01:55');
